// Minimal i18n (no dependency). English is the source language and the dictionary key:
//   t("Save project")                         → "Spara projekt" in Swedish
//   t("{n} {n|panel|panels}", { n: 3 })        → "3 paneler"     (placeholder {n|one|other} picks by n === 1)
// Messages generated by the core modules (errors, guidance) stay English data; `tr()` translates
// them at DISPLAY time by matching the same templates. Shared with Elham Fold Studio and Dieline Creator.
import { useSyncExternalStore } from "react";
import { SV } from "./sv";

export type Lang = "en" | "sv";
export const LANGS: { id: Lang; name: string; short: string }[] = [{ id: "en", name: "English", short: "EN" }, { id: "sv", name: "Svenska", short: "SV" }];
const KEY = "elham-lang";
type Params = Record<string, string | number>;

function initialLang(): Lang {
  try { const v = localStorage.getItem(KEY); if (v === "en" || v === "sv") return v; } catch { /* storage blocked */ }
  try { return typeof navigator !== "undefined" && /^sv\b/i.test(navigator.language || "") ? "sv" : "en"; } catch { return "en"; }
}
let lang: Lang = initialLang();
const listeners = new Set<() => void>();
const syncDocument = () => { if (typeof document !== "undefined") document.documentElement.lang = lang; };
syncDocument();

export const getLang = (): Lang => lang;
export function setLang(next: Lang) {
  if (next === lang) return;
  lang = next;
  try { localStorage.setItem(KEY, next); } catch { /* private mode: in-memory only */ }
  syncDocument();
  for (const l of listeners) l();
}
const subscribe = (l: () => void) => { listeners.add(l); return () => { listeners.delete(l); }; };
/** Re-renders the calling component when the language changes. */
export const useLang = (): Lang => useSyncExternalStore(subscribe, getLang, getLang);

// ---- templates
const PH = /\{(\w+)(?:\|([^|}]*)\|([^}]*))?\}/g;
function fill(template: string, params?: Params): string {
  if (!params) return template;
  return template.replace(PH, (m, k: string, one?: string, other?: string) => {
    const v = params[k];
    if (v === undefined) return m;
    if (one !== undefined) return Number(v) === 1 ? one : other!;
    return String(v);
  });
}
/** Marks a string as a dictionary key without translating it (for constant tables translated later with t()). */
export const tk = (en: string) => en;
/** Translates a UI string (English source text as key). Missing translations fall back to English. */
export function t(en: string, params?: Params): string {
  return fill(lang === "sv" ? SV[en] ?? en : en, params);
}
/** Translates into a given language regardless of the current one (tests, documentation). */
export function tIn(l: Lang, en: string, params?: Params): string {
  return fill(l === "sv" ? SV[en] ?? en : en, params);
}

// ---- display-time translation of generated English text
interface Pattern { re: RegExp; names: string[]; sv: string; literal: number }
let patterns: Pattern[] | null = null;
const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
function compile(): Pattern[] {
  const out: Pattern[] = [];
  for (const [en, sv] of Object.entries(SV)) {
    if (!en.includes("{")) continue;
    const names: string[] = [];
    let src = "", last = 0;
    for (const m of en.matchAll(PH)) {
      src += esc(en.slice(last, m.index)); last = m.index! + m[0].length;
      if (m[2] !== undefined) src += `(?:${esc(m[2])}|${esc(m[3])})`;
      else if (names.includes(m[1])) src += `(?:.*?)`;
      else { src += "(.*?)"; names.push(m[1]); }
    }
    src += esc(en.slice(last));
    out.push({ re: new RegExp(`^${src}$`, "s"), names, sv, literal: en.replace(PH, "").length });
  }
  // more literal text = more specific: tried first
  return out.sort((a, b) => b.literal - a.literal);
}
function translateOne(text: string, depth: number): string | null {
  const exact = SV[text];
  if (exact !== undefined) return exact;
  if (depth > 3) return null;
  for (const p of (patterns ??= compile())) {
    const m = p.re.exec(text);
    if (!m) continue;
    const params: Params = {};
    p.names.forEach((n, i) => { const v = m[i + 1]; params[n] = translateText(v, depth + 1); });
    return fill(p.sv, params);
  }
  return null;
}
const SENTENCE = /(?<=[.!?])\s+(?=[A-Z“"(0-9])/;
/** Whole text, else sentence by sentence; untranslatable parts stay English. */
function translateText(text: string, depth: number): string {
  if (!text || !/[A-Za-z]/.test(text)) return text;
  const whole = translateOne(text, depth);
  if (whole !== null) return whole;
  const parts = text.split(SENTENCE);
  if (parts.length < 2) return text;
  return parts.map((s) => translateOne(s, depth + 1) ?? s).join(" ");
}
/**
 * Translates generated English text (import messages, fold reasons, preflight checks) into the
 * current language: whole-text template match first, then sentence by sentence. Anything without a
 * translation is shown unchanged (English), never dropped.
 */
export function tr(text: string): string {
  return lang === "en" ? text : translateText(text, 0);
}
/** tr() into a given language (tests). */
export function trIn(l: Lang, text: string): string {
  const prev = lang; lang = l;
  try { return tr(text); } finally { lang = prev; }
}
/** For tests: the compiled template list size. */
export const _patternCount = () => (patterns ??= compile()).length;
